public static METArrivalDockCopyController construct()
{
    return new METArrivalDockCopyController();
}

    public static void main(Args _args)
    {
        // Get marked records from calling form
        if (_args && _args.caller() is FormRun)
        {
            WMSArrivalOverviewTmp WMSArrivalOverviewTmpTest;
            FormRun  FormRun= _args.caller();
            FormDataSource WMSArrivalOverviewTmpDs = FormRun.dataSource(formDataSourceStr(WMSArrivalOverview,WMSArrivalOverviewTmp));
            WMSArrivalOverviewTmpDs.filter(fieldNum(WMSArrivalOverviewTmp, Selected), queryValue(NoYes::Yes));
            InventTransRefId    PrevInventTransRefId;
            WMSArrivalOverviewTmpDs.first();
            WMSArrivalOverviewTmp WMSArrivalOverviewTmp = WMSArrivalOverviewTmpDs.cursor();
            while (WMSArrivalOverviewTmp && WMSArrivalOverviewTmp.InventTransRefId != PrevInventTransRefId)
            {
                Info(WMSArrivalOverviewTmp.InventTransRefId);
                PrevInventTransRefId = WMSArrivalOverviewTmp.InventTransRefId;
                METArrivalDockCopyContract rdpContract = new METArrivalDockCopyContract();
                rdpContract.parmInventTransType(WMSArrivalOverviewTmp.InventTransType);
                rdpContract.parmInventTransRefId(WMSArrivalOverviewTmp.InventTransRefId);

                METArrivalDockCopyController METArrivalDockCopyController = METArrivalDockCopyController::construct();
                METArrivalDockCopyController.parmReportName(ssrsReportStr(METArrivalDockCopy, Report));
                METArrivalDockCopyController.parmReportContract().parmRdpContract(rdpContract);

                SRSPrintDestinationSettings printDestinationSettings = new SRSPrintDestinationSettings();
                printDestinationSettings.parmFileName(WMSArrivalOverviewTmp.InventTransRefId + '.pdf');
                printDestinationSettings.fileFormat(SRSReportFileFormat::PDF);
                printDestinationSettings.printMediumType(SRSPrintMediumType::File);

                SrsReportDataContract reportDataContract = new SrsReportDataContract();
                reportDataContract.unpack(METArrivalDockCopyController.parmReportContract().pack());
                reportDataContract.parmReportExecutionInfo(new SRSReportExecutionInfo());
                reportDataContract.parmPrintSettings(printDestinationSettings);

                new SrsReportRunService().runReport(reportDataContract);

                Browser br = new Browser();

                System.IO.Stream stream = new System.IO.MemoryStream(reportDataContract.parmReportBytes());

                str downloadurl = File::SendFileToTempStore(stream, printDestinationSettings.parmFileName(), classstr(FileUploadTemporaryStorageStrategy), true);

                new Browser().navigate(downloadurl, true, false);

                WMSArrivalOverviewTmpDs.next();
                WMSArrivalOverviewTmp =WMSArrivalOverviewTmpDs.cursor();
            }
            WMSArrivalOverviewTmpDs.removeFilter();
        }

    }
